char *const argv_sh[] = { "/bin/sh", "-c", "echo ok", NULL };
char *const envp_std[] = { "LANG=C", NULL };

// Example 1: Use CWD (AT_FDCWD) like standard execve(2)
execveat(
    AT_FDCWD,
    "/usr/bin/touch",
    argv_sh,
    envp_std,
    0
);

// Example 2: Resolve path relative to a directory FD
int target_dir_fd = 5; // Assume this FD points to '/usr'

// Executes '/usr/bin/ls'
execveat(
    target_dir_fd,
    "bin/ls",
    argv_sh,
    envp_std,
    0 // flags (e.g., AT_EXECVE_RESTRICT_AT)
);

// If execveat returns, failure occurred (e.g., errno EPERM)
